async function isPassStillActive(passId) {
  const now = Date.now();
  const hit = PASS_CACHE.get(passId);
  if (hit && now - hit.ts < CACHE_TTL_MS) {
    return hit.ok;
  }
  const data = await callPublicRpc('check_test_pass_active', { p_pass_id: passId });
  const ok = Boolean(data && data.ok);
  PASS_CACHE.set(passId, { ts: now, ok });
  return ok;
}

/**
 * Verifies L0 Master Session, L1 Signed Preview Token, or L2 Guest Pass Token.
 * Returns { ok: boolean, tier: 'L0'|'L1'|'L2'|null, allowedVariants: string[] }
 */
async function resolvePreviewAuth(domain, cookies) {
  if (cookies.__sm_master_sess && (await verifyAdminSession(cookies.__sm_master_sess))) {
    return { ok: true, tier: 'L0', allowedVariants: ALLOWED_VARIANTS };
  }
  const secret = process.env.STEALTH_PREVIEW_SECRET;
  const token = cookies.__sm_prv;
  if (!secret || !token || typeof token !== 'string') {
    return { ok: false, tier: null, allowedVariants: [] };
  }

  // Check L2 format: l2~domain~passId~a,b,c~exp~sig
  if (token.startsWith('l2~')) {
    const parts = token.split('~');
    if (parts.length !== 6) return { ok: false, tier: null, allowedVariants: [] };
    const [, tDom, passId, varsCsv, expStr, sig] = parts;
    const exp = Number(expStr);
    if (!Number.isFinite(exp) || exp * 1000 < Date.now()) {
      return { ok: false, tier: null, allowedVariants: [] };
    }
    if (tDom !== '*' && tDom !== domain) {
      return { ok: false, tier: null, allowedVariants: [] };
    }
    const payload = `l2~${tDom}~${passId}~${varsCsv}~${expStr}`;
    const expected = await hmacHex(secret, payload);
    if (!timingSafeEq(expected, sig)) {
      return { ok: false, tier: null, allowedVariants: [] };
    }
    const active = await isPassStillActive(passId);
    if (!active) {
      return { ok: false, tier: null, allowedVariants: [] };
    }
    const allowed = varsCsv
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter((s) => ALLOWED_VARIANTS.includes(s));
    return { ok: true, tier: 'L2', allowedVariants: allowed.length ? allowed : ['a'] };
  }

  // L1 format: exp.sig
  const parts = token.split('.');
  if (parts.length !== 2) return { ok: false, tier: null, allowedVariants: [] };
  const exp = Number(parts[0]);
  const sig = parts[1];
  if (!Number.isFinite(exp) || exp * 1000 < Date.now()) {
    return { ok: false, tier: null, allowedVariants: [] };
  }
  const candidates = [
    `prv|${domain}|${exp}`,
    `prv|*|${exp}`,
    `prv|${domain.split('.')[0]}.vercel.app|${exp}`,
  ];
  for (const cand of candidates) {
    const expected = await hmacHex(secret, cand);
    if (timingSafeEq(expected, sig)) {
      return { ok: true, tier: 'L1', allowedVariants: ALLOWED_VARIANTS };
    }
  }
  return { ok: false, tier: null, allowedVariants: [] };
}

