async function selectVariant(gate, auth, cookies, secret, vid, userAgent) {
  const variants = normalizeVariants(gate.variants);
  const defKey = ALLOWED_VARIANTS.includes(gate.default_variant) ? gate.default_variant : 'a';

  if (auth.ok && cookies.__sm_ab_pin && ALLOWED_VARIANTS.includes(cookies.__sm_ab_pin)) {
    if (auth.allowedVariants.includes(cookies.__sm_ab_pin)) {
      return cookies.__sm_ab_pin;
    }
  }
  if (auth.ok && auth.tier === 'L2' && auth.allowedVariants.length > 0 && !auth.allowedVariants.includes(defKey)) {
    return auth.allowedVariants[0];
  }

  const shouldBucket =
    gate.mode === 'ab_live' ||
    gate.mode === 'canary' ||
    (auth.ok && Boolean(gate.ab_enabled));

  if (!shouldBucket) return defKey;
  if (BOT_UA_RE.test(userAgent || '')) return defKey;

  const bps = await computeBucketBps(secret, `${gate.domain}|${gate.exp_id || 'exp_v1'}|${gate.exp_salt || 's1'}|${vid}`);
  const totalWeight = variants.reduce((acc, item) => acc + (Number(item.weight) || 0), 0);
  if (totalWeight <= 0) return defKey;

  let cursor = 0;
  for (const item of variants) {
    const span = Math.round(((Number(item.weight) || 0) / totalWeight) * 10000);
    cursor += span;
    if (bps < cursor) return item.key;
  }
  return defKey;
}

async function proxyAdminApiToMaster(request, domain) {
  const headers = securityHeaders('application/json; charset=utf-8');
  let rawBody = '{}';
  let parsed = {};
  try {
    rawBody = await request.text();
    parsed = JSON.parse(rawBody || '{}');
  } catch {
    return new Response(JSON.stringify({ ok: false, errorCode: 'ERR_BAD_JSON' }), { status: 400, headers });
  }

  if (parsed.action === 'logout') {
    return new Response(JSON.stringify({ ok: true }), {
      status: 200,
      headers: {
        ...headers,
        'Set-Cookie': '__sm_master_sess=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax',
      },
    });
  }

  const cookies = parseCookies(request.headers.get('cookie') || '');
  const fwdHeaders = {
    'Content-Type': 'application/json',
    'User-Agent': 'ShineMight-EdgeAdminProxy/2.0',
  };
  if (cookies.__sm_master_sess) {
    fwdHeaders.Cookie = `__sm_master_sess=${encodeURIComponent(cookies.__sm_master_sess)}`;
  }

  try {
    const upRes = await fetch('https://admin.shinemight.com/__stealth_api', {
      method: 'POST',
      headers: fwdHeaders,
      body: rawBody,
      cache: 'no-store',
    });
    const data = await upRes.json();
    GATE_CACHE.delete(domain);

    if (parsed.action === 'login' && upRes.ok && data && data.ok) {
      const secret = process.env.STEALTH_PREVIEW_SECRET;
      const exp = Math.floor(Date.now() / 1000) + 7 * 86400;
      const sessToken = data.token || (secret ? `${exp}.${await hmacHex(secret, `master_admin|${exp}`)}` : '');
      const prvToken = await signL1PreviewToken(domain, exp);
      const resHeaders = new Headers(headers);
      if (sessToken) {
        resHeaders.append('Set-Cookie', `__sm_master_sess=${sessToken}; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax`);
      }
      if (prvToken) {
        resHeaders.append('Set-Cookie', `__sm_prv=${prvToken}; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax`);
      }
      return new Response(JSON.stringify({ ok: true }), { status: 200, headers: resHeaders });
    }

    return new Response(JSON.stringify(data), { status: upRes.status, headers });
  } catch {
    return new Response(JSON.stringify({ ok: false, errorCode: 'ERR_NETWORK' }), { status: 502, headers });
  }
}

async function handleLocalTestApi(request, domain) {
  const headers = securityHeaders('application/json; charset=utf-8');
  let body = {};
  try {
    body = await request.json();
  } catch {
    return new Response(JSON.stringify({ ok: false, errorCode: 'PASS_INVALID' }), { status: 400, headers });
  }

  if (body.action === 'redeem') {
    const code = String(body.code || '').trim();
    if (!code) {
      return new Response(JSON.stringify({ ok: false, errorCode: 'PASS_INVALID' }), { status: 400, headers });
    }

    // 1) Try L2 Guest Pass RPC first if formatted like pass or try both
    const rpcRes = await callPublicRpc('redeem_test_pass', { p_code: code, p_host: domain });
    if (rpcRes && rpcRes.ok) {
      const expSec = Number(rpcRes.expires_epoch) || Math.floor(Date.now() / 1000) + 86400;
      const maxAge = Math.max(60, expSec - Math.floor(Date.now() / 1000));
      const allowed = Array.isArray(rpcRes.allowed_variants) ? rpcRes.allowed_variants : ['a', 'b', 'c'];
      const l2Tok = await signL2GuestToken(domain, rpcRes.pass_id, allowed, expSec);
      const resHeaders = new Headers(headers);
      resHeaders.append('Set-Cookie', `__sm_prv=${encodeURIComponent(l2Tok)}; Path=/; Max-Age=${maxAge}; HttpOnly; Secure; SameSite=Lax`);
      if (allowed[0]) {
        resHeaders.append('Set-Cookie', `__sm_ab_pin=${allowed[0]}; Path=/; Max-Age=${maxAge}; Secure; SameSite=Lax`);
      }
      return new Response(JSON.stringify({ ok: true, tier: 'L2', allowedVariants: allowed }), { status: 200, headers: resHeaders });
    }

    // 2) Try L0 Admin Master Key verification
    let masterOk = false;
    if (typeof verifyMasterPassword === 'function' && process.env.STEALTH_SUPABASE_SERVICE_KEY) {
      masterOk = await verifyMasterPassword(code);
    } else {
      try {
        const loginUp = await fetch('https://admin.shinemight.com/__stealth_api', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'login', key: code }),
          cache: 'no-store',
        });
        const ld = await loginUp.json();
        masterOk = Boolean(loginUp.ok && ld && ld.ok);
      } catch {}
    }

    if (masterOk) {
      const exp = Math.floor(Date.now() / 1000) + 7 * 86400;
      const secret = process.env.STEALTH_PREVIEW_SECRET;
      const sessSig = secret ? await hmacHex(secret, `master_admin|${exp}`) : '';
      const prvTok = await signL1PreviewToken(domain, exp);
      const resHeaders = new Headers(headers);
      if (sessSig) {
        resHeaders.append('Set-Cookie', `__sm_master_sess=${exp}.${sessSig}; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax`);
      }
      if (prvTok) {
        resHeaders.append('Set-Cookie', `__sm_prv=${prvTok}; Path=/; Max-Age=604800; HttpOnly; Secure; SameSite=Lax`);
      }
      return new Response(JSON.stringify({ ok: true, tier: 'L0', allowedVariants: ALLOWED_VARIANTS }), { status: 200, headers: resHeaders });
    }

    const errCode = (rpcRes && rpcRes.errorCode && rpcRes.errorCode !== 'PASS_INVALID')
      ? rpcRes.errorCode
      : 'PASS_INVALID';
    return new Response(JSON.stringify({ ok: false, errorCode: errCode }), { status: 401, headers });
  }

  return new Response(JSON.stringify({ ok: false, errorCode: 'PASS_INVALID' }), { status: 400, headers });
}

async function handleStandardStealthRequest(request, passThroughFn, masterAdminApiFn) {
  const url = new URL(request.url);
  const rawHost =
    request.headers.get('x-sm-orig-host') ||
    request.headers.get('x-forwarded-host') ||
    request.headers.get('host') ||
    url.hostname;
  const hostLower = String(rawHost || '').toLowerCase().trim().split(':')[0];
  const domain = normalizeHost(rawHost);
  const pathname = url.pathname;

  // 0. Fast unforgeable internal hop bypass (prevents re-entry during HTML injection fetch)
  const internalTok = request.headers.get('x-sm-internal-pass');
  if (internalTok && (await verifyInternalPassToken(domain, internalTok))) {
    return passThroughFn();
  }

  const cookies = parseCookies(request.headers.get('cookie') || '');
  const isZh = detectZh(request);

  // 1. Dedicated admin.shinemight.com host OR canonical /test/admin across ALL matrix domains
  if (pathname === '/__stealth_api' && request.method === 'POST') {
    if (typeof masterAdminApiFn === 'function' && process.env.STEALTH_SUPABASE_SERVICE_KEY) {
      const isAuthed = await verifyAdminSession(cookies.__sm_master_sess);
      return masterAdminApiFn(request, isAuthed);
    }
    return proxyAdminApiToMaster(request, domain);
  }

  if (pathname === '/__sm_test_api' && request.method === 'POST') {
    return handleLocalTestApi(request, domain);
  }

  if (pathname === '/__sm_ab_event' && request.method === 'POST') {
    let evBody = {};
    try { evBody = await request.json(); } catch {}
    const gate = await fetchGatePolicy(domain);
    await callPublicRpc('record_ab_event', {
      p_host: domain,
      p_exp_id: String(evBody.exp_id || gate.exp_id || 'exp_v1'),
      p_variant: String(evBody.variant || cookies.__sm_v || gate.default_variant || 'a'),
      p_event: String(evBody.event || 'exposure'),
    });
    return new Response(JSON.stringify({ ok: true }), {
      status: 200,
      headers: securityHeaders('application/json; charset=utf-8'),
    });
  }

  if (hostLower === 'admin.shinemight.com' || pathname === '/test/admin' || pathname === '/test/admin/') {
    const isAuthed = await verifyAdminSession(cookies.__sm_master_sess);
    if (!isAuthed) {
      const adminGateObj = {
        domain: hostLower === 'admin.shinemight.com' ? 'admin.shinemight.com' : `${domain}/test/admin`,
        mode: 'maintenance',
        brand_name_zh: '全矩阵门禁与实验总控',
        brand_name_en: 'Matrix Gate & A/B/C Admin',
        tagline_zh: '受保护控制平面',
        tagline_en: 'Protected Control Plane',
        notice_zh: '当前控制节点已启用零信任门禁保护，请验证管理员主控密钥进入。',
        notice_en: 'Zero-trust protection is active. Unlock with your administrator key.',
        contact_email: '',
      };
      return new Response(renderStealthHtml(adminGateObj, isZh, true), {
        status: 200,
        headers: securityHeaders('text/html; charset=utf-8'),
      });
    }
    if (hostLower === 'admin.shinemight.com' && (url.searchParams.get('portal') === '1' || pathname.startsWith('/assets/'))) {
      return passThroughFn();
    }
    const focusDom = hostLower === 'admin.shinemight.com' ? '' : domain;
    return new Response(renderAdminConsoleHtml(isZh, focusDom), {
      status: 200,
      headers: securityHeaders('text/html; charset=utf-8'),
    });
  }

  // 2. Canonical /test/exit & legacy /__preview_exit
  if (pathname === '/test/exit' || pathname === '/__preview_exit') {
    const resHeaders = new Headers({
      Location: '/',
      'Cache-Control': 'no-store',
    });
    resHeaders.append('Set-Cookie', '__sm_prv=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax');
    resHeaders.append('Set-Cookie', '__sm_ab_pin=; Path=/; Max-Age=0; Secure; SameSite=Lax');
    resHeaders.append('Set-Cookie', '__sm_master_sess=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax');
    return new Response(null, { status: 302, headers: resHeaders });
  }

  // 3. Cryptographic preview token handoff (?__sm_preview=...) — works on /, /test, /test/a|b|c
  const previewParam = url.searchParams.get('__sm_preview');
  if (previewParam && (await verifyL1QueryToken(domain, previewParam))) {
    url.searchParams.delete('__sm_preview');
    const variantParam = url.searchParams.get('__sm_var');
    url.searchParams.delete('__sm_var');
    const cleanDest = url.pathname + (url.search ? url.search : '');
    const resHeaders = new Headers({
      Location: cleanDest || '/',
      'Cache-Control': 'no-store',
    });
    resHeaders.append('Set-Cookie', `__sm_prv=${encodeURIComponent(previewParam)}; Path=/; Max-Age=86400; HttpOnly; Secure; SameSite=Lax`);
    if (variantParam && ALLOWED_VARIANTS.includes(variantParam)) {
      resHeaders.append('Set-Cookie', `__sm_ab_pin=${variantParam}; Path=/; Max-Age=86400; Secure; SameSite=Lax`);
    }
    return new Response(null, { status: 302, headers: resHeaders });
  }

  // 4. Canonical /test/share/<code> one-click L2 Guest Pass redemption
  if (pathname.startsWith('/test/share/')) {
    const rawCode = decodeURIComponent(pathname.slice('/test/share/'.length).split('/')[0] || '').trim();
    const rpcRes = await callPublicRpc('redeem_test_pass', { p_code: rawCode, p_host: domain });
    if (!rpcRes || !rpcRes.ok) {
      const ec = (rpcRes && rpcRes.errorCode) || 'PASS_INVALID';
      return new Response(null, {
        status: 302,
        headers: { Location: `/test?err=${encodeURIComponent(ec)}`, 'Cache-Control': 'no-store' },
      });
    }
    const expSec = Number(rpcRes.expires_epoch) || Math.floor(Date.now() / 1000) + 86400;
    const maxAge = Math.max(60, expSec - Math.floor(Date.now() / 1000));
    const allowed = Array.isArray(rpcRes.allowed_variants) ? rpcRes.allowed_variants : ['a', 'b', 'c'];
    const l2Tok = await signL2GuestToken(domain, rpcRes.pass_id, allowed, expSec);
    const reqVar = (url.searchParams.get('v') || allowed[0] || 'a').toLowerCase();
    const pinVar = allowed.includes(reqVar) ? reqVar : (allowed[0] || 'a');
    const resHeaders = new Headers({ Location: '/', 'Cache-Control': 'no-store' });
    resHeaders.append('Set-Cookie', `__sm_prv=${encodeURIComponent(l2Tok)}; Path=/; Max-Age=${maxAge}; HttpOnly; Secure; SameSite=Lax`);
    resHeaders.append('Set-Cookie', `__sm_ab_pin=${pinVar}; Path=/; Max-Age=${maxAge}; Secure; SameSite=Lax`);
    return new Response(null, { status: 302, headers: resHeaders });
  }

  // 5. Resolve active preview auth & live gate policy
  const auth = await resolvePreviewAuth(domain, cookies);
  const gate = await fetchGatePolicy(domain);

  // 6. Canonical /test Launchpad
  if (pathname === '/test' || pathname === '/test/') {
    const nextPath = url.searchParams.get('next') || '/';
    const errCode = url.searchParams.get('err') || '';
    const html = renderTestPortalHtml(gate, auth, cookies.__sm_ab_pin || '', isZh, nextPath, errCode);
    return new Response(html, { status: 200, headers: securityHeaders('text/html; charset=utf-8') });
  }

  // 7. Canonical /test/a, /test/b, /test/c (+ deep link support /test/b/sub/path)
  const testVarMatch = pathname.match(/^\/test\/([abc])(\/.*)?$/i);
  if (testVarMatch) {
    const targetVar = testVarMatch[1].toLowerCase();
    const restPath = testVarMatch[2] || '/';
    const dest = restPath + (url.search ? url.search : '');
    if (!auth.ok) {
      return new Response(null, {
        status: 302,
        headers: {
          Location: `/test?next=${encodeURIComponent(pathname + (url.search || ''))}`,
          'Cache-Control': 'no-store',
        },
      });
    }
    if (!auth.allowedVariants.includes(targetVar)) {
      return new Response(null, {
        status: 302,
        headers: { Location: '/test?err=PASS_VARIANT_FORBIDDEN', 'Cache-Control': 'no-store' },
      });
    }
    const resHeaders = new Headers({ Location: dest, 'Cache-Control': 'no-store' });
    resHeaders.append('Set-Cookie', `__sm_ab_pin=${targetVar}; Path=/; Max-Age=86400; Secure; SameSite=Lax`);
    return new Response(null, { status: 302, headers: resHeaders });
  }

  // 8. Evaluate Root-Domain Gate Permission
  const vid = cookies.__sm_vid || randomVid();
  const needSetVid = !cookies.__sm_vid;
  // Bucketing seed only (never used for auth/session verification).
  const secret = process.env.STEALTH_PREVIEW_SECRET || 'sm-ab-seed';

  let allowedThrough = false;
  if (auth.ok || gate.mode === 'live' || gate.mode === 'ab_live') {
    allowedThrough = true;
  } else if (gate.mode === 'canary' && Number(gate.canary_percent) > 0) {
    const canaryBps = await computeBucketBps(secret, `canary|${domain}|${vid}`);
    if (canaryBps < Number(gate.canary_percent) * 100) {
      allowedThrough = true;
    }
  }

  // 9. Blocked -> Render Stealth Maintenance / Brand Page & Crawler Shields
  if (!allowedThrough) {
    const isBrandMode = gate.mode === 'brand';
    if (pathname === '/robots.txt') {
      if (isBrandMode) {
        return new Response(
          `User-agent: *\nAllow: /\nDisallow: /test\nDisallow: /__sm_\nSitemap: https://${publicHostForDomain(domain)}/sitemap.xml\n`,
          { status: 200, headers: securityHeaders('text/plain; charset=utf-8', true) }
        );
      }
      return new Response('User-agent: *\nDisallow: /\n', {
        status: 200,
        headers: securityHeaders('text/plain; charset=utf-8'),
      });
    }
    if (pathname === '/sitemap.xml' && isBrandMode) {
      const hostPub = publicHostForDomain(domain);
      const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  <url><loc>https://${escapeHtml(hostPub)}/</loc></url>\n</urlset>\n`;
      return new Response(xml, {
        status: 200,
        headers: securityHeaders('application/xml; charset=utf-8', true),
      });
    }
    if (pathname === '/sitemap.xml' || pathname.endsWith('.xml')) {
      return new Response('Not Found', {
        status: 404,
        headers: securityHeaders('text/plain; charset=utf-8'),
      });
    }
    if (pathname === '/manifest.webmanifest' || pathname === '/manifest.json') {
      const bName = gate.brand_name_zh || gate.domain;
      return new Response(
        JSON.stringify({
          name: bName,
          short_name: bName,
          start_url: '/',
          display: 'standalone',
          background_color: '#000000',
          theme_color: '#000000',
        }),
        { status: 200, headers: securityHeaders('application/manifest+json; charset=utf-8') }
      );
    }
    if (pathname === '/favicon.ico' || pathname === '/icon.svg' || pathname === '/apple-touch-icon.png') {
      return new Response(renderMonogramSvg(gate.brand_name_en || gate.domain), {
        status: 200,
        headers: securityHeaders('image/svg+xml; charset=utf-8'),
      });
    }
    if (pathname.startsWith('/api/') || (request.method !== 'GET' && request.method !== 'HEAD')) {
      return new Response(
        JSON.stringify({
          ok: false,
          errorCode: 'SERVICE_UNDER_MAINTENANCE',
          message: isZh ? '系统维护升级中，暂不开放服务调用。' : 'System is currently under maintenance.',
        }),
        { status: 503, headers: securityHeaders('application/json; charset=utf-8') }
      );
    }
    return new Response(renderStealthHtml(gate, isZh, false), {
      status: 200,
      headers: securityHeaders('text/html; charset=utf-8', isBrandMode),
    });
  }

  // 10. Allowed Through -> Determine Active Variant (A/B/C) & Sandbox Status
  const ua = request.headers.get('user-agent') || '';
  const activeVariant = await selectVariant(gate, auth, cookies, secret, vid, ua);
  const variants = normalizeVariants(gate.variants);
  const variantObj = variants.find((v) => v.key === activeVariant) || variants[0];
  const isBu02 = gate.bu_code === 'BU-02' || BU02_DOMAINS.has(domain);
  const isSandbox = Boolean(isBu02 && gate.mode !== 'live');

  // Protect /test/* from crawlers even when live
  if (pathname === '/robots.txt' && (gate.mode === 'live' || gate.mode === 'ab_live')) {
    return new Response(`User-agent: *\nAllow: /\nDisallow: /test\nDisallow: /__sm_\nSitemap: https://${publicHostForDomain(domain)}/sitemap.xml\n`, {
      status: 200,
      headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'public, max-age=300' },
    });
  }

  // 11. Cross-Deployment Origin Proxy (if variantObj.origin is configured)
  const customOrigin = variantObj && variantObj.origin ? variantObj.origin : '';
  let targetOriginUrl = null;
  if (customOrigin && /^https?:\/\//i.test(customOrigin)) {
    try {
      const parsedOrig = new URL(customOrigin);
      if (parsedOrig.hostname.toLowerCase() !== url.hostname.toLowerCase()) {
        targetOriginUrl = new URL(pathname + url.search, parsedOrig.origin);
      }
    } catch {}
  }

  const accept = request.headers.get('accept') || '';
  const isHtmlNav =
    request.method === 'GET' &&
    accept.includes('text/html') &&
    !request.headers.get('range') &&
    !pathname.startsWith('/api/') &&
    !pathname.startsWith('/_next/') &&
    !STATIC_EXT_RE.test(pathname);

  const needsHtmlInjection =
    isHtmlNav &&
    (auth.ok || gate.mode === 'ab_live' || gate.mode === 'canary' || Boolean(gate.ab_enabled) || Boolean(targetOriginUrl));

  // Fast zero-buffer pass-through for static assets, APIs, and pure live traffic without active experiment/preview
  if (!targetOriginUrl && !needsHtmlInjection) {
    const baseRes = await passThroughFn();
    const outHeaders = new Headers(baseRes.headers);
    applyBaselineSecurityHeaders(outHeaders);
    outHeaders.set('X-SM-Variant', activeVariant);
    if (isSandbox) outHeaders.set('X-SM-Sandbox', '1');
    if (needSetVid) {
      outHeaders.append('Set-Cookie', `__sm_vid=${vid}; Path=/; Max-Age=7776000; Secure; SameSite=Lax`);
    }
    if (cookies.__sm_v !== activeVariant) {
      outHeaders.append('Set-Cookie', `__sm_v=${activeVariant}; Path=/; Max-Age=86400; Secure; SameSite=Lax`);
    }
    if (auth.ok) {
      outHeaders.set('X-Robots-Tag', 'noindex, nofollow, noarchive');
      outHeaders.set('Cache-Control', 'private, no-store, max-age=0');
    }
    return new Response(baseRes.body, { status: baseRes.status, headers: outHeaders });
  }

  // Perform internal fetch (for HTML Zero-CLS head script + TestFlight HUD injection OR custom variant origin proxy)
  try {
    const fetchUrl = targetOriginUrl ? targetOriginUrl.toString() : url.toString();
    const fwdHeaders = new Headers(request.headers);
    fwdHeaders.delete('accept-encoding');
    fwdHeaders.set('x-sm-variant', activeVariant);
    fwdHeaders.set('x-sm-exp-id', gate.exp_id || 'exp_v1');
    fwdHeaders.set('x-sm-env', auth.ok ? 'test' : 'prod');
    if (isSandbox) fwdHeaders.set('x-sm-sandbox', 'true');
    if (targetOriginUrl) {
      fwdHeaders.set('Host', targetOriginUrl.host);
      fwdHeaders.set('X-SM-Orig-Host', rawHost);
    } else {
      const internalTok = await makeInternalPassToken(domain);
      if (internalTok) {
        fwdHeaders.set('x-sm-internal-pass', internalTok);
      }
    }

    const hasBody = request.method !== 'GET' && request.method !== 'HEAD';
    const upRes = await fetch(fetchUrl, {
      method: request.method,
      headers: fwdHeaders,
      body: hasBody ? request.body : undefined,
      redirect: 'manual',
    });

    const outHeaders = new Headers(upRes.headers);
    applyBaselineSecurityHeaders(outHeaders);
    outHeaders.set('X-SM-Variant', activeVariant);
    if (isSandbox) outHeaders.set('X-SM-Sandbox', '1');
    if (needSetVid) {
      outHeaders.append('Set-Cookie', `__sm_vid=${vid}; Path=/; Max-Age=7776000; Secure; SameSite=Lax`);
    }
    if (cookies.__sm_v !== activeVariant) {
      outHeaders.append('Set-Cookie', `__sm_v=${activeVariant}; Path=/; Max-Age=86400; Secure; SameSite=Lax`);
    }
    if (auth.ok) {
      outHeaders.set('X-Robots-Tag', 'noindex, nofollow, noarchive');
      outHeaders.set('Cache-Control', 'private, no-store, max-age=0');
    }

    const ct = (upRes.headers.get('content-type') || '').toLowerCase();
    if (isHtmlNav && ct.includes('text/html') && upRes.status >= 200 && upRes.status < 400) {
      let html = await upRes.text();
      const headInject =
        `<script>window.__SM_AB__=${JSON.stringify({
          v: activeVariant,
          exp: gate.exp_id || 'exp_v1',
          mode: gate.mode,
          env: auth.ok ? 'test' : 'prod',
          sandbox: isSandbox,
        })};document.documentElement.dataset.smVariant=${JSON.stringify(activeVariant)};</script>` +
        (gate.mode === 'ab_live' && !html.includes('rel="canonical"')
          ? `<link rel="canonical" href="https://${publicHostForDomain(domain)}${pathname}" />`
          : '');

      if (/<head[^>]*>/i.test(html)) {
        html = html.replace(/<head[^>]*>/i, (m) => m + headInject);
      } else {
        html = headInject + html;
      }

      if (auth.ok) {
        const hud = buildPillHudSnippet(domain, activeVariant, gate.mode, isSandbox, auth.tier || 'L1', auth.allowedVariants, isZh);
        if (/<\/body>/i.test(html)) {
          html = html.replace(/<\/body>/i, hud + '</body>');
        } else {
          html = html + hud;
        }
      }

      // Record exposure asynchronously if A/B active
      if (!auth.ok && (gate.mode === 'ab_live' || gate.mode === 'canary') && !BOT_UA_RE.test(ua)) {
        callPublicRpc('record_ab_event', {
          p_host: domain,
          p_exp_id: gate.exp_id || 'exp_v1',
          p_variant: activeVariant,
          p_event: 'exposure',
        }).catch(() => {});
      }

      outHeaders.delete('content-length');
      outHeaders.delete('content-encoding');
      return new Response(html, { status: upRes.status, headers: outHeaders });
    }

    return new Response(upRes.body, { status: upRes.status, headers: outHeaders });
  } catch {
    return passThroughFn();
  }
}

export async function middleware(request: NextRequest): Promise<Response> {
  return handleStandardStealthRequest(request, () => NextResponse.next());
}

export const config = {
  matcher: ['/:path*'],
};
